import React, { Component } from 'react';
import './Hero.css';
// import Heroimg from "./mobile.jpg"
import Heroimg from "./Adobe Express - file (2).png"
export class HeroSection extends Component {
  render() {
    return (
      <div className="hero-container rounded-top-5 rounded-bottom-5">
        <div className="hero-text">
        <p className='hero-heading'><i className="fa-solid fa-phone first-icon rounded-top-3 rounded-bottom-3"></i> RingEX</p>
        <p className='hero-text1'><strong>The reliable Business<br /> communications <br /> platform</strong></p>
        <p className='hero-text2'>Empower every employee with AI-powered calls messages ,<br /> and meetings across devices.</p>
        <a href='/' className=" rounded-pill hero-btn">ExploreRingEx</a>
            <div className="products-container">
  <ul className="product-column">
    <li><span>|</span> Phone <i className="fa-solid fa-arrow-right"></i></li>
    <li><span>|</span> Online Fax <i className="fa-solid fa-arrow-right"></i></li>
    <li><span>|</span> Messaging <i className="fa-solid fa-arrow-right"></i></li>
  </ul>
  <ul className="product-column">
    <li><span>|</span> Messaging <i className="fa-solid fa-arrow-right"></i></li>
    <li><span>|</span> Video Meeting <i className="fa-solid fa-arrow-right"></i></li>
    <li><span>|</span> Open Platform <i className="fa-solid fa-arrow-right"></i></li>
  </ul>
</div>
        </div>

<div className="hero-img ">
  <img src={Heroimg}alt="" />
</div>
      </div>
    );
  }
}

export default HeroSection;
