import React from "react";
import "./Logos.css"; 
import AWS1 from "./AWS1.svg";
import Grid from "./Grid-leader-2025.svg";
import Hp from "./HP.svg";
import Restore from "./Restoration-Hardware.svg";
import Target from "./Target.svg";



const LogosSlider = () => {
  const logos = [
     <img src={AWS1} alt="Logo 1" className="logo-img" style={{height:'40px'}} />,
     <img src={Grid} alt="Logo 1" className="logo-img" style={{height:'40px'}} />,
     <img src={Hp} alt="Logo 1" className="logo-img" style={{height:'40px'}} />,
     <img src={Restore} alt="Logo 1" className="logo-img" style={{height:'40px'}} />,
     <img src={Target} alt="Logo 1" className="logo-img" style={{height:'40px'}} />,
   
    "🚀", "🔥", "💻"
  ];

  return (
    <div className="slider-container">
      <div className="slider-track">
        {logos.map((logo, index) => (
          <span key={index} className="logo">
            {logo}
          </span>
        ))}
        {/* Duplicate for smooth infinite loop */}
        {logos.map((logo, index) => (
          <span key={index + 10} className="logo">
            {logo}
          </span>
        ))}
      </div>
    </div>
  );
};

export default LogosSlider;
