import React, { Component } from 'react'
import "./Main.css"
import Mainimg from "./ai-agent-banner-desktop-mobile.jpg"
import lineimg1 from "./line-pic.webp"
import lineimg2 from "./rc-trends-img.jpg"
import logoai from "./ai-icon-png-rendition.webp"

export class Main extends Component {
    render() {
        return (
            <>
                <div className='main-container1'>
                    <div className='ai-main-container'>
                        <img className='rounded-top rounded-bottom ai-pic' src={Mainimg} alt="AI Banner" />
                    </div>
                    <div className='text-btn'>
                        <p className='ai-text'>AI for everyone</p>
                        <p className='meet-text'>
                            <img src={logoai} alt="AI Icon" className='logo-ai' />
                            <span className='aiasistent'>AI </span>
                            <span className='speak-text'>that speaks the</span>
                        </p>

                        <p className='paragraph'>
                            Power every interaction with AI that integrates seamlessly across your calls, messages,
                            meetings, and contact center. Personalize customer experiences, get real-time insights,
                            and create effortless workflows across all your conversations.
                        </p>
                        <div className='container-btnwatch'>
                            <a href='/' className='rounded-pill watch-btn watch-btn1'>
                                <i className="fa-solid fa-circle-play"></i> watch video
                            </a>
                            <a href='/' className='rounded-pill watch-btn watch-btn2'>learn more</a>
                        </div>
                    </div>
                </div>

                <div className='main-container-pic'>
                    <div className="line-pic">
                        <div className="firstpic-container">
                            <img className='rounded-top-5 rounded-bottom-5 first-img' src={lineimg1} alt="Gartner Recognition" />
                            <div className='text-gartner-container'>
                                <p className='main-text'>
                                    <strong>
                                        Gartner® names RingCentral a Magic Quadrant™<br />Leader for the 10th year in a row
                                    </strong>
                                </p>
                                <p className='main-firsttext'>
                                    RingCentral is proud to be recognised as a 2024 Gartner Magic Quadrant Leader for <br /> UCaaS worldwide.
                                </p>
                                <a href='/' className='rounded-pill report-btn'>Get the report</a>
                            </div>
                        </div>

                        <div className='secondpic-container'>
                            <img className='rounded-top-5 rounded-bottom-5 second-img' src={lineimg2} alt="AI Trends Report" />
                            <div className='text-gartner-container2'>
                                <p className='main-text'>
                                    <strong>
                                        2025 Trends: The State of AI in Business <br />Communications
                                    </strong>
                                </p>
                                <p className='main-secondtext'>
                                    Our quarterly report provides a comprehensive overview of AI's current role in business <br />communications,
                                    with forward-looking predictions from industry leaders.
                                </p>
                                <a href='/' className='learn-btn rounded-pill'>Learn more</a>
                            </div>
                        </div>
                    </div>
                </div>
            </>
        )
    }
}

export default Main
