import React, { Component } from 'react';
import "./Section.css";
import { Link } from 'react-router-dom';

export class SectionFirst extends Component {
  render() {
    return (
      <div className='container-nav1'>
        <h1 className='first-text'>
          Bring employee and customer <br />
          experiences together to drive growth
        </h1>

        <nav className='navbar1 rounded-pill'>
          <Link to='/business' className='btn-phone rounded-pill'>Business Phone</Link>
          <Link to='/contact' className='btn-center rounded-pill'>Contact Center</Link>
          <Link to='/conversation' className='btn-intelligence rounded-pill'>Conversation Intelligence</Link>
          <Link to='/events' className='btn-events rounded-pill'>Events</Link>
        </nav>
      </div>
    );
  }
}

export default SectionFirst;

