import React, { Component } from 'react'
import "./Industry.css"
import Healthcare from "./healthcare.jpg"
import ringlogo from "./ring-logo.png"
import { Link } from 'react-router-dom'
export class Industry extends Component {
    render() {
        return (
            <div className='industry-container'>
            <p className='industry-heading'><strong>Solutions for every industry</strong></p>
                <nav className='links'>
                    <Link to='/healthcare' className='rounded-pill healthbtn'>Healthcare</Link>
                    <Link to='/financial' className='rounded-pill industrybtn'>Financial Serivce</Link>
                    <Link to='/education' className='rounded-pill industrybtn'>Education</Link>
                    <Link to='/retail' className='rounded-pill industrybtn'>Retail</Link>
                    <Link to='/govt' className='rounded-pill industrybtn'>Government</Link>
                </nav>
                <div className="industry-pic">
                    <div className="pic">
                        <img src={Healthcare} alt="" style={{height:'400px'}}/>
                    </div>
                    <div className="industry-text">
                   
                            <p className='smart-text'><strong>Create smart, secure experiences <br />
                        for patients, staff, and partners.</strong></p>
<div className='industry-btn rounded-pill'>
     <a href='/' className='learn-text '>Learn more <i class="fa-solid fa-arrow-right learn-icon"></i></a>
</div>
                    
                    <hr />
                   <div className='d-flex ring-logo'>
                     <img src={ringlogo} alt=""  style={{height:'30px'}}/>
                    <p><strong>42% increase in HCAHPS <br />patient satisfaction</strong></p>
                         </div>
                  
                   </div>
                </div>

                
            </div>
        )
    }
}

export default Industry
